```bash
cd /home/vscode/nullness-benchmarks/gson && { nl -ba gson/src/main/java/com/google/gson/internal/LinkedHashTreeMap.java | sed -n '280,420p'; sed -n '240,270p' gson/src/main/java/com/google/gson/internal/LinkedHashTreeMap.java; sed -n '240,270p' gson/src/main/java/com/google/gson/internal/LinkedHashTreeMap.java | sed -n '1,40p'; perl -0pi -e 's/void removeInternal\(Node<K, V> node, boolean unlink\) \{
    if \(unlink\) \{
      node\.prev\.next = node\.next;
      node\.next\.prev = node\.prev;
      node\.next = node\.prev = null; // Help the GC \(for performance\)
    \}
/void removeInternal(Node<K, V> node, boolean unlink) {
    if (unlink) {
      Node<K, V> prev = node.prev;
      Node<K, V> next = node.next;
      if (prev != null && next != null) {
        prev.next = next;
        next.prev = prev;
      }
      node.next = node.prev = null; // Help the GC \(for performance\)
    }
/' gson/src/main/java/com/google/gson/internal/LinkedHashTreeMap.java; ./gradlew :gson:compileJava -x test -q > new_build_output.log 2>&1; grep -n "LinkedHashTreeMap.java" new_build_output.log || true; tail -n 40 new_build_output.log; }```

